package com.hmdp.ai.integration;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.mcp.*;import com.hmdp.ai.infrastructure.external.SafeHttpClient;import com.hmdp.ai.infrastructure.mcp.*;import com.hmdp.ai.infrastructure.model.SecretResolutionService;import com.sun.net.httpserver.HttpServer;import org.junit.jupiter.api.Test;import java.net.InetSocketAddress;import java.nio.charset.StandardCharsets;import java.util.Collections;import static org.assertj.core.api.Assertions.assertThat;
class McpToolIntegrationTest {@Test void discoversAndInvokesStreamableHttpMcpTool()throws Exception{ObjectMapper mapper=new ObjectMapper();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/mcp",exchange->{JsonNode request=mapper.readTree(exchange.getRequestBody());String method=request.path("method").asText();JsonNode result;if("tools/list".equals(method))result=mapper.createObjectNode().set("tools",mapper.createArrayNode().add(mapper.createObjectNode().put("name","echo").put("description","echo").set("inputSchema",mapper.createObjectNode().put("type","object"))));else if("tools/call".equals(method))result=mapper.createObjectNode().set("content",mapper.createArrayNode().add(mapper.createObjectNode().put("type","text").put("text",request.path("params").path("arguments").path("value").asText())));else result=mapper.createObjectNode().put("protocolVersion","2025-03-26");byte[]body=mapper.writeValueAsBytes(mapper.createObjectNode().put("jsonrpc","2.0").set("result",result));exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(200,body.length);exchange.getResponseBody().write(body);exchange.close();});server.start();try{McpClientFactory factory=new McpClientFactory(new SafeHttpClient(),new SecretResolutionService(Collections.emptyList()),mapper);McpHttpClient client=factory.create();McpServer definition=new McpServer("id","t","w","local","local","local",McpTransport.HTTP,"http://127.0.0.1:"+server.getAddress().getPort()+"/mcp",null,"[]",2000,true,"UP",true,null,"ACTIVE");assertThat(client.tools(definition)).extracting(McpToolDescriptor::getName).containsExactly("echo");assertThat(client.execute(definition,"echo",mapper.createObjectNode().put("value","ok")).path("content").get(0).path("text").asText()).isEqualTo("ok");}finally{server.stop(0);}}}
